  const drive = [(P.dk || []).length ? DKP[l] + ' ' + DK.filter(k => P.dk.includes(k)).join(', ') : '', P.car ? CAR[l] : ''].filter(Boolean).join(', ');
  o.p = Object.assign({}, P, {birth: fmtDate(P.birth), nat, civil: civ, drive, city: [P.zip, P.town].filter(Boolean).join(' ')});
  o.exp = d.exp.map(e => Object.assign({}, e, {sub: [[e.org, e.place].filter(Boolean).join(', '), tr(JOBT[e.type], l), e.pct ? e.pct + (l === 'en' ? '%' : ' %') : ''].filter(Boolean).join(' · ')}));
  o.edu = d.edu.map(e => Object.assign({}, e, {title: [tr(DEG[e.deg], l), e.title].filter(Boolean).join(' – ')}));
  o.lng = d.lng.map(x => { const ct = x.lvl === 'native' ? '' : (x.cert === 'other' ? (x.certT || '') : (x.cert || '')); return Object.assign({}, x, {ct, lvT: [(L[l] || L.de).lv[x.lvl] || '', ct].filter(Boolean).join(', ')}); });
  const sel = new Set(d.skl || []), rows = [];
  SKC.forEach(c => { const v = c.items.filter(it => sel.has(sid(c.id, it))).map(it => iname(it, l)); if (v.length) rows.push([c.t[LI[l] + 1], v.map((x, i) => i ? x : cap(x)).join(', ')]); });
  String(d.skills || '').split('\n').map(x => x.trim()).filter(Boolean).forEach(x => rows.push(['', x]));
  o.skillRows = rows;
  const iset = new Set(d.ints || []), iv = [];
  INC.forEach(c => c.items.forEach(it => { if (iset.has(c.id + '.' + it[1])) iv.push(it[LI[l] + 1]); }));
  const own = String(d.interests || '').trim();
